1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
nfp: flower: Fix a potential leak in
 nfp_tunnel_add_shared_mac()

ida_simple_get() returns an id between min (0) and max (NFP_MAX_MAC_INDEX)
inclusive.
So NFP_MAX_MAC_INDEX (0xff) is a valid id.

In order for the error handling path to work correctly, the 'invalid'
value for 'ida_idx' should not be in the 0..NFP_MAX_MAC_INDEX range,
inclusive.

So set it to -1.

Fixes: 20cce8865098 ("nfp: flower: enable MAC address sharing for offloadable devs")
Signed-off-by: Christophe JAILLET <christophe.jaillet@wanadoo.fr>
Signed-off-by: Simon Horman <simon.horman@corigine.com>
Link: https://lore.kernel.org/r/20220218131535.100258-1-simon.horman@corigine.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The bug was caused by the incorrect initialization of the `ida_idx` variable to `NFP_MAX_MAC_INDEX`, which is a valid ID. This led to potential memory leaks in the error handling path, as the code would incorrectly attempt to remove an ID from the ID allocator even when it was not properly allocated. The error handling logic needed to distinguish between a valid ID and an uninitialized state, which was not correctly implemented.

Here is the patch:

 static int
 nfp_tunnel_add_shared_mac(struct nfp_app *app, struct net_device *netdev,
 			  int port, bool mod)
 {
 	struct nfp_flower_priv *priv = app->priv;
-	int ida_idx = NFP_MAX_MAC_INDEX, err;
 	struct nfp_tun_offloaded_mac *entry;
+	int ida_idx = -1, err;
 	u16 nfp_mac_idx = 0;

 	entry = nfp_tunnel_lookup_offloaded_macs(app, netdev->dev_addr);
 	if (entry && nfp_tunnel_is_mac_idx_global(entry->index)) {
 		if (entry->bridge_count ||
 		    !nfp_flower_is_supported_bridge(netdev)) {
 			nfp_tunnel_offloaded_macs_inc_ref_and_link(entry,
 								   netdev, mod);
 			return 0;
 		}

 		/* MAC is global but matches need to go to pre_tun table. */
 		nfp_mac_idx = entry->index | NFP_TUN_PRE_TUN_IDX_BIT;
 	}

 	if (!nfp_mac_idx) {
 		/* Assign a global index if non-repr or MAC is now shared. */
 		if (entry || !port) {
 			ida_idx = ida_simple_get(&priv->tun.mac_off_ids, 0,
 						 NFP_MAX_MAC_INDEX, GFP_KERNEL);
 			if (ida_idx < 0)
 				return ida_idx;

 			nfp_mac_idx =
 				nfp_tunnel_get_global_mac_idx_from_ida(ida_idx);

 			if (nfp_flower_is_supported_bridge(netdev))
 				nfp_mac_idx |= NFP_TUN_PRE_TUN_IDX_BIT;

 		} else {
 			nfp_mac_idx =
 				nfp_tunnel_get_mac_idx_from_phy_port_id(port);
 		}
 	}

 	if (!entry) {
 		entry = kzalloc(sizeof(*entry), GFP_KERNEL);
 		if (!entry) {
 			err = -ENOMEM;
 			goto err_free_ida;
 		}

 		ether_addr_copy(entry->addr, netdev->dev_addr);
 		INIT_LIST_HEAD(&entry->repr_list);

 		if (rhashtable_insert_fast(&priv->tun.offloaded_macs,
 					   &entry->ht_node,
 					   offloaded_macs_params)) {
 			err = -ENOMEM;
 			goto err_free_entry;
 		}
 	}

 	err = __nfp_tunnel_offload_mac(app, netdev->dev_addr,
 				       nfp_mac_idx, false);
 	if (err) {
 		/* If not shared then free. */
 		if (!entry->ref_count)
 			goto err_remove_hash;
 		goto err_free_ida;
 	}

 	entry->index = nfp_mac_idx;
 	nfp_tunnel_offloaded_macs_inc_ref_and_link(entry, netdev, mod);

 	return 0;

 err_remove_hash:
 	rhashtable_remove_fast(&priv->tun.offloaded_macs, &entry->ht_node,
 			       offloaded_macs_params);
 err_free_entry:
 	kfree(entry);
 err_free_ida:
-	if (ida_idx != NFP_MAX_MAC_INDEX)
+	if (ida_idx != -1)
 		ida_simple_remove(&priv->tun.mac_off_ids, ida_idx);

 	return err;
 }



